# -*- coding: utf-8 -*-
"""Fault injection, interruption and scale acceptance tests.

Covers A41 (streaming scale without silent truncation), A48 (no half-published
state after a disk failure or a kill), A49 (two writers on one version) and A50
(a checkpoint that no longer matches must not be resumed as if it did).

Design rules for this module:

* **Every fixture is synthetic.**  The CSVs are generated by
  ``faults.big_csv``; no user corpus, network or external service is touched.
  The scale test is marked SYNTHETIC where it matters.
* **Expected values are fixed here and independent of the module under test.**
  Row counts come from ``big_csv``'s documented contract and are cross-checked
  with a plain ``csv`` line count; content hashes are computed with ``hashlib``
  directly (never with ``contract_v2.file_sha256``); the crash point is proven
  by a marker file written by the child process immediately before
  ``os._exit`` plus the fact that ``UNREACHABLE`` never prints.
* The modules under test (``txn``, ``contract_v2``, ``lifecycle``,
  ``verify_dataset``) are used as-is; nothing in them is modified by this file.
"""
from __future__ import annotations

import errno
import hashlib
import json
import os
import subprocess
import textwrap
import time
import tracemalloc
from pathlib import Path

from _helpers import PYTHON, SCRIPTS, TempCase

import contract_v2 as C
import faults as F
import lifecycle as L
import txn as T


# ---------------------------------------------------------------------------
# independent helpers (deliberately not the pipeline's own implementations)
# ---------------------------------------------------------------------------
def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_path(path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        for block in iter(lambda: fh.read(1 << 20), b""):
            digest.update(block)
    return digest.hexdigest()


def data_rows(path) -> int:
    """Reference data-row count of a CSV file (header excluded)."""
    with open(path, "rb") as fh:
        return sum(1 for _ in fh) - 1


class _PipelineCase(TempCase):
    """Shared fixture helpers; each test gets its own project under ``tmp``."""

    def project(self) -> C.Project:
        return C.Project(self.tmp)

    def write(self, rel: str, text: str) -> str:
        path = Path(self.tmp, rel)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        return os.fspath(path)

    def publish_v1(self, proj, target: str = "results/table1.csv",
                   content: bytes = b"a,b\n1,2\n"):
        txn = T.Transaction(proj, label="table1")
        txn.stage(target, content)
        return txn, txn.commit(message="v1")

    @staticmethod
    def child_source(body: str) -> str:
        return "import sys\nsys.path.insert(0, %r)\n" % SCRIPTS + body

    def run_child(self, body: str) -> subprocess.CompletedProcess:
        return subprocess.run([PYTHON, "-c", self.child_source(body)],
                              capture_output=True, text=True, timeout=180)

    def start_child(self, body: str) -> subprocess.Popen:
        return subprocess.Popen([PYTHON, "-c", self.child_source(body)],
                                stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, text=True)

    @staticmethod
    def last_json(stdout: str) -> dict:
        lines = [line for line in stdout.strip().splitlines() if line.strip()]
        return json.loads(lines[-1])


# ---------------------------------------------------------------------------
# the fault instruments themselves must not be no-ops
# ---------------------------------------------------------------------------
class TestFaultPrimitives(_PipelineCase):
    def test_disk_full_writes_a_real_prefix_then_raises_enospc(self):
        root = Path(self.tmp, "objects")
        root.mkdir()
        target = root / "artifact.bin"
        outside = Path(self.tmp, "outside.bin")

        with F.disk_full(root) as fault:
            with self.assertRaises(OSError) as caught:
                target.write_bytes(b"0123456789")

        self.assertEqual(caught.exception.errno, errno.ENOSPC)
        self.assertEqual(fault.failures, 1)
        self.assertEqual(fault.attempts, 1)
        self.assertEqual(fault.records[0]["requested_bytes"], 10)
        self.assertEqual(fault.records[0]["written_bytes"], 5)
        self.assertTrue(target.is_file(), "disk_full must leave a torn file")
        self.assertEqual(target.read_bytes(), b"01234")   # half, byte for byte
        self.assertFalse(F.files_identical(target, root / "missing.bin"))

        # writes outside the injected root keep working
        with F.disk_full(root):
            outside.write_bytes(b"safe")
        self.assertEqual(outside.read_bytes(), b"safe")

    def test_disk_full_honours_after_bytes(self):
        root = Path(self.tmp, "objects")
        root.mkdir()
        target = root / "artifact.bin"
        with F.disk_full(root, after_bytes=3):
            with self.assertRaises(OSError):
                target.write_bytes(b"0123456789")
        self.assertEqual(target.read_bytes(), b"012")

        empty = root / "empty.bin"
        with F.disk_full(root, after_bytes=0):
            with self.assertRaises(OSError):
                empty.write_bytes(b"xyz")
        self.assertEqual(empty.read_bytes(), b"")

    def test_files_identical_is_content_based(self):
        a = self.write("a.txt", "same\n")
        b = self.write("nested/b.txt", "same\n")
        c = self.write("c.txt", "different\n")
        self.assertTrue(F.files_identical(a, b))
        self.assertFalse(F.files_identical(a, c))
        self.assertFalse(F.files_identical(a, self.p("missing.txt")))

    def test_big_csv_streams_the_declared_row_count(self):
        path = self.p("small.csv")
        self.assertEqual(F.big_csv(path, 1000, cols=6, seed=3), 1000)
        self.assertEqual(data_rows(path), 1000)
        with open(path, encoding="utf-8", newline="") as fh:
            header = next(fh).rstrip("\r\n").split(",")
            first = next(fh)
            last = list(fh)[-1]
        self.assertEqual(header, ["case_id", "group", "x1", "x2", "x3", "y"])
        self.assertTrue(first.startswith("C0000000,"), first)
        self.assertTrue(last.startswith("C0000999,"), last)

        again = self.p("small-again.csv")
        F.big_csv(again, 1000, cols=6, seed=3)
        self.assertTrue(F.files_identical(path, again),
                        "same seed must produce the same synthetic fixture")


# ---------------------------------------------------------------------------
# A48: disk full during a publish attempt
# ---------------------------------------------------------------------------
class TestPublishUnderDiskFailure(_PipelineCase):
    def test_published_pointer_survives_enospc_during_object_write(self):
        proj = self.project()
        v1_content = b"a,b\n1,2\n"
        _, first = self.publish_v1(proj, content=v1_content)
        self.assertEqual(T.read_published(proj, "results/table1.csv"), v1_content)

        v2_content = b"a,b\n3,4\n"
        v2 = T.Transaction(proj, label="table1")
        v2.stage("results/table1.csv", v2_content)

        with F.disk_full(proj.path("objects")) as fault:
            with self.assertRaises(OSError) as caught:
                v2.commit()

        self.assertEqual(caught.exception.errno, errno.ENOSPC)
        self.assertGreaterEqual(fault.failures, 1)
        self.assertEqual(fault.records[0]["source"], "os.replace")
        self.assertEqual(v2.state, "open", "a failed commit must not claim success")
        self.assertEqual(T.recover(proj, v2.run_id)["state"], "interrupted")

        # the published version did not move and is still readable/verifiable
        pointer = T.read_pointer(proj)
        self.assertEqual(pointer["commit"], first["commit"])
        self.assertEqual(T.read_published(proj, "results/table1.csv"), v1_content)
        self.assertTrue(T.verify_commit(proj, first["commit"]))
        self.assertTrue(T.verify_commit(proj))

        # an explicit failure record is what recovery then reports
        info = v2.fail("ENOSPC while storing objects", exc=caught.exception)
        self.assertEqual(info["state"], "failed")
        self.assertEqual(T.recover(proj, v2.run_id)["state"], "failed")
        self.assertEqual(T.read_pointer(proj)["commit"], first["commit"])

    def test_torn_object_is_never_adopted_as_an_artifact(self):
        proj = self.project()
        v1_content = b"a,b\n1,2\n"
        _, first = self.publish_v1(proj, content=v1_content)

        v2_content = b"a,b\n7,8\n"
        v2_sha = sha256_bytes(v2_content)
        v2 = T.Transaction(proj, label="table1")
        v2.stage("results/table1.csv", v2_content)

        with F.disk_full(proj.path("objects")) as fault:
            with self.assertRaises(OSError):
                v2.commit()

        torn = proj.path("objects", v2_sha)
        self.assertTrue(torn.is_file(), "disk_full must leave a real torn file")
        torn_bytes = torn.read_bytes()
        self.assertLess(len(torn_bytes), len(v2_content))
        self.assertEqual(torn_bytes, v2_content[:len(torn_bytes)])
        self.assertNotEqual(sha256_path(torn), v2_sha)
        self.assertEqual(fault.records[0]["target"], os.fspath(torn))

        # no commit manifest points at the torn object (or at the failed run)
        manifests = [json.loads(path.read_text(encoding="utf-8"))
                     for path in proj.path("commits").glob("*.json")]
        self.assertTrue(manifests)
        for manifest in manifests:
            self.assertNotEqual(manifest.get("run_id"), v2.run_id)
            for entry in manifest["entries"]:
                self.assertNotEqual(entry["sha256"], v2_sha)
        self.assertEqual(T.read_pointer(proj)["commit"], first["commit"])
        self.assertTrue(T.verify_commit(proj))

        # a retry must refuse the torn object instead of silently adopting it
        retry = T.Transaction(proj, label="table1")
        retry.stage("results/table1.csv", v2_content)
        with self.assertRaises(T.PublishError) as caught:
            retry.commit()
        self.assertIn("corrupt", str(caught.exception))
        self.assertEqual(T.read_pointer(proj)["commit"], first["commit"])
        self.assertEqual(T.read_published(proj, "results/table1.csv"), v1_content)


# ---------------------------------------------------------------------------
# A48: the process is killed between the object/manifest writes and the pointer
# ---------------------------------------------------------------------------
class TestCrashBeforePointerReplace(_PipelineCase):
    def test_crash_before_pointer_replace_keeps_previous_version(self):
        proj = self.project()
        v1_content = b"a,b\n1,2\n"
        _, first = self.publish_v1(proj, content=v1_content)

        v2_content = b"a,b\n5,6\n"
        marker = self.p("crash.json")
        body = textwrap.dedent(f"""
            import contract_v2 as C
            import faults as F
            import txn as T
            p = C.Project({self.tmp!r})
            t = T.Transaction(p, run_id="crashed-run", label="table1")
            t.stage("results/table1.csv", {v2_content!r})
            with F.crash_at("pointer", 1, marker={marker!r}):
                t.commit()
            print("UNREACHABLE")
        """)
        proc = self.run_child(body)

        self.assertEqual(proc.returncode, 9, proc.stderr)
        self.assertNotIn("UNREACHABLE", proc.stdout)
        receipt = json.loads(Path(marker).read_text(encoding="utf-8"))
        self.assertEqual(receipt["step"], "pointer")
        self.assertEqual(receipt["kind"], "replace")
        self.assertTrue(receipt["target"].endswith("published.json"),
                        receipt["target"])

        # the object and the manifest were written before the kill ...
        self.assertTrue(proj.path("objects", sha256_bytes(v2_content)).is_file())
        manifests = [json.loads(path.read_text(encoding="utf-8"))
                     for path in proj.path("commits").glob("*.json")]
        crashed = [m for m in manifests if m.get("run_id") == "crashed-run"]
        self.assertEqual(len(crashed), 1)

        # ... but the publish pointer never moved
        self.assertEqual(T.read_pointer(proj)["commit"], first["commit"])
        self.assertEqual(T.read_published(proj, "results/table1.csv"), v1_content)
        self.assertTrue(T.verify_commit(proj, first["commit"]))

        state = T.recover(proj, "crashed-run")
        self.assertIn(state["state"], ("committed", "interrupted"))
        self.assertFalse(state.get("published", False),
                         "a manifest that was never published is not 'published'")


# ---------------------------------------------------------------------------
# A50: checkpoints and cache entries expire when the world moves
# ---------------------------------------------------------------------------
class TestCheckpointInvalidation(_PipelineCase):
    def setUp(self):
        super().setUp()
        self.write("data/analysis.csv", "case,y\n1,2\n")
        self.write("scripts/model.py", "print('model v1')\n")
        self.write("rules/coding.md", "coding rule v1\n")
        self.write("output/model.json", '{"n": 1}\n')
        self.proj = C.Project(self.tmp)
        self.checkpoint = C.make_record(
            "checkpoint", "cp:model:r1",
            {"step": "model", **self.bindings()},
            producer=C.producer_for(
                "hardening-fixture",
                module_file=os.path.join(SCRIPTS, "contract_v2.py")),
            status="valid")
        self.proj.append("checkpoint", self.checkpoint)

    def bindings(self) -> dict:
        """The current five layers; hashed here with hashlib (not the module)."""
        return {
            "inputs": {"data/analysis.csv":
                       sha256_path(self.p("data/analysis.csv"))},
            "code": {"scripts/model.py": sha256_path(self.p("scripts/model.py"))},
            "rules": {"rules/coding.md": sha256_path(self.p("rules/coding.md"))},
            "environment": {"python": "3.12", "pandas": "2.3.3"},
            "review_version": "review-1",
        }

    def resume(self, step_id: str) -> dict:
        """The recovery rule: only a fully matching checkpoint may resume."""
        state = T.checkpoint_state(self.checkpoint, self.bindings())
        if state["valid"]:
            return {"resumed": True, "state": state, "record": None}
        record = L.finish(
            self.proj, step_id, status="failed",
            detail="checkpoint invalid: " + ",".join(
                mismatch["layer"] for mismatch in state["mismatches"]))
        return {"resumed": False, "state": state, "record": record}

    def test_checkpoint_matches_only_unchanged_inputs_and_code(self):
        unchanged = T.checkpoint_state(self.checkpoint, self.bindings())
        self.assertTrue(unchanged["valid"])
        self.assertEqual(unchanged["mismatches"], [])
        self.assertEqual(unchanged["layers_checked"],
                         ["inputs", "code", "rules", "environment",
                          "review_version"])

        # (a) the input file moved -> only the inputs layer mismatches
        self.write("data/analysis.csv", "case,y\n1,3\n")
        state = T.checkpoint_state(self.checkpoint, self.bindings())
        self.assertFalse(state["valid"])
        self.assertEqual([m["layer"] for m in state["mismatches"]], ["inputs"])

        # (b) the code moved (input restored)
        self.write("data/analysis.csv", "case,y\n1,2\n")
        self.write("scripts/model.py", "print('model v2')\n")
        state = T.checkpoint_state(self.checkpoint, self.bindings())
        self.assertFalse(state["valid"])
        self.assertEqual([m["layer"] for m in state["mismatches"]], ["code"])

        # (c) the review version moved (code restored)
        self.write("scripts/model.py", "print('model v1')\n")
        moved_review = self.bindings()
        moved_review["review_version"] = "review-2"
        state = T.checkpoint_state(self.checkpoint, moved_review)
        self.assertFalse(state["valid"])
        self.assertEqual([m["layer"] for m in state["mismatches"]],
                         ["review_version"])

        # (d) nothing moved again -> the checkpoint matches again
        self.assertTrue(T.checkpoint_state(self.checkpoint,
                                           self.bindings())["valid"])

        # a crashed run must refuse the mismatched checkpoint, not fake a finish
        self.write("scripts/model.py", "print('model v2')\n")
        L.plan(self.proj, [{"id": "fit", "goal": "fit M1", "tool": "python"}])
        L.start(self.proj, "fit")
        outcome = self.resume("fit")
        self.assertFalse(outcome["resumed"])
        self.assertEqual([m["layer"] for m in outcome["state"]["mismatches"]],
                         ["code"])
        self.assertEqual(outcome["record"]["status"], "failed")
        statuses = [r["status"] for r in
                    self.proj.revisions("workflow_step", "fit")]
        self.assertEqual(statuses, ["planned", "running", "failed"])
        self.assertNotIn("completed", statuses)
        self.assertNotIn("fit", L.ready(self.proj))
        self.assertIn("code", outcome["record"]["data"]["run_state"]["detail"])

    def test_stale_cache_entry_cannot_stand_in_for_a_completed_run(self):
        inputs = {"data/analysis.csv":
                  sha256_path(self.p("data/analysis.csv"))}
        code = {"scripts/model.py": sha256_path(self.p("scripts/model.py"))}
        rules = {"rules/coding.md": sha256_path(self.p("rules/coding.md"))}
        environment = {"python": "3.12"}
        key = L.cache_key(inputs=inputs, code=code, rules=rules,
                          environment=environment, label="fit")
        L.put(self.proj, key, artifact="output/model.json", inputs=inputs,
              code=code, rules=rules, environment=environment)
        entry = self.proj.latest("cache_entry", key)
        self.assertTrue(L.is_valid(self.proj, entry)["valid"])

        # the input changes, so the cached artifact may not be reused
        self.write("data/analysis.csv", "case,y\n1,3\n")
        state = L.is_valid(self.proj, entry)
        self.assertFalse(state["valid"])
        self.assertEqual(state["problems"],
                         [{"path": "data/analysis.csv", "problem": "changed"}])

        reused = L.reuse(self.proj, key, run_id="resume-after-crash")
        self.assertFalse(reused["reused"])
        self.assertEqual(reused["state"], "stale")
        self.assertEqual(self.proj.latest("cache_entry", key)["status"], "stale")
        # no completed run was invented for the "resume"
        self.assertEqual(self.proj.read("workflow_step"), [])


# ---------------------------------------------------------------------------
# A50: a killed process is cancelled, never completed
# ---------------------------------------------------------------------------
class TestTimeoutCancellation(_PipelineCase):
    def test_killed_child_is_not_recorded_completed(self):
        proj = self.project()
        L.plan(proj, [{"id": "fit", "goal": "fit M1", "tool": "python"}])
        L.start(proj, "fit")

        sentinel = self.p("child-finished.json")
        body = ("import time\n"
                "time.sleep(60)\n"
                "open(%r, 'w', encoding='utf-8').write('{}')\n" % sentinel)
        code = F.kill_process([PYTHON, "-c", body], after_seconds=1.0)

        self.assertIsNotNone(code)
        self.assertNotEqual(code, 0,
                            "a force-killed child must not report success")
        print(f"[timeout] child killed after 1.0 s, exit code={code}")
        self.assertFalse(os.path.exists(sentinel),
                         "the child was killed before its final write")
        self.assertEqual(L.states(proj)["fit"]["status"], "running")

        record = L.finish(proj, "fit", status="cancelled",
                          detail="killed after 1.0 s timeout")
        self.assertEqual(record["status"], "cancelled")
        self.assertEqual(L.states(proj)["fit"]["status"], "cancelled")
        self.assertNotIn("fit", L.ready(proj))
        terminal = [r["status"] for r in proj.revisions("workflow_step", "fit")
                    if r["status"] not in ("planned", "running")]
        self.assertEqual(terminal, ["cancelled"])


# ---------------------------------------------------------------------------
# A41: synthetic scale, full accounting
# ---------------------------------------------------------------------------
class TestScale(_PipelineCase):
    """SYNTHETIC scale test: the 200k/50k CSVs are generated, never user data.

    Budget on the development machine: the 200k fixture is ~11 MB and takes
    ~1 s to write and ~0.3 s to read in 25k chunks, so the whole class runs in
    a few seconds.  If a machine cannot do 200k rows, lower ``ROWS`` to 100_000
    (and say so in a comment); do not skip the test - the accounting assertions
    are the point, not the absolute size.
    """

    ROWS = 200_000
    CHUNK = 25_000
    # Peak memory bound: 3x the file OR 400 MB, whichever is looser.  The bound
    # is deliberately loose because tracemalloc cannot see every native buffer
    # pandas/numpy allocate; a genuinely out-of-control read still fails it.
    # The sharper streaming evidence is the chunk accounting below.
    MEMORY_BUDGET = 400 * 1024 * 1024

    def test_chunked_read_accounts_for_every_row_of_a_synthetic_200k_csv(self):
        import pandas as pd

        path = self.p("synthetic-200k.csv")
        self.assertEqual(F.big_csv(path, self.ROWS, cols=6, seed=7), self.ROWS)
        expected = data_rows(path)            # plain-python reference count
        self.assertEqual(expected, self.ROWS)
        size = os.path.getsize(path)

        chunk_sizes: list[int] = []
        first_id = last_id = None
        tracemalloc.start()
        try:
            total = 0
            for chunk in pd.read_csv(path, chunksize=self.CHUNK):
                chunk_sizes.append(len(chunk))
                total += len(chunk)
                if first_id is None:
                    first_id = chunk.iloc[0]["case_id"]
                last_id = chunk.iloc[-1]["case_id"]
            peak = tracemalloc.get_traced_memory()[1]
        finally:
            tracemalloc.stop()

        self.assertEqual(total, expected, "chunked read lost rows")
        self.assertEqual(sum(chunk_sizes), expected)
        self.assertEqual(len(chunk_sizes), self.ROWS // self.CHUNK)
        self.assertTrue(all(n <= self.CHUNK for n in chunk_sizes), chunk_sizes)
        self.assertEqual(first_id, "C0000000")
        # the tail is present: a silent head/tail truncation would show here
        self.assertEqual(last_id, f"C{self.ROWS - 1:07d}")

        limit = max(3 * size, self.MEMORY_BUDGET)
        self.assertLess(peak, limit,
                        f"tracemalloc peak {peak / 1e6:.1f} MB against limit "
                        f"{limit / 1e6:.1f} MB for a {size / 1e6:.1f} MB CSV")
        print(f"[scale] rows={total} size={size / 1e6:.2f} MB "
              f"chunks={chunk_sizes} peak={peak / 1e6:.2f} MB "
              f"limit={limit / 1e6:.2f} MB")

        # control: reading the whole frame at once costs visibly more, which
        # shows the chunked pass above really streams instead of accumulating
        tracemalloc.start()
        try:
            frame = pd.read_csv(path)
            full_peak = tracemalloc.get_traced_memory()[1]
            self.assertEqual(len(frame), self.ROWS)
            self.assertEqual(list(frame.columns),
                             ["case_id", "group", "x1", "x2", "x3", "y"])
        finally:
            del frame
            tracemalloc.stop()
        self.assertLess(peak, full_peak,
                        "chunked read should peak below a full-frame read")
        print(f"[scale] full-frame peak={full_peak / 1e6:.2f} MB "
              f"(control for the chunked pass above)")

    def test_verify_dataset_reads_all_rows_of_a_50k_csv(self):
        import verify_dataset as V

        path = self.p("synthetic-50k.csv")
        self.assertEqual(F.big_csv(path, 50_000, cols=6, seed=11), 50_000)
        reference = data_rows(path)
        self.assertEqual(reference, 50_000)

        header, rows = V.read_csv(path)      # the real entry point
        self.assertEqual(len(rows), reference)
        self.assertEqual(header,
                         ["case_id", "group", "x1", "x2", "x3", "y"])
        self.assertEqual(rows[0]["case_id"], "C0000000")
        # big_csv documents case_id == f"C{i:07d}" (0-based, 7-digit zero pad)
        self.assertEqual(rows[-1]["case_id"], "C0049999")
        self.assertEqual(len({row["case_id"] for row in rows}), 50_000,
                         "every synthetic case must appear exactly once")


# ---------------------------------------------------------------------------
# A49: two processes publishing one version
# ---------------------------------------------------------------------------
class TestConcurrentCommit(_PipelineCase):
    def test_two_processes_publishing_the_same_commit_leave_one_current_version(self):
        proj = self.project()
        content = "case,group,y\n1,a,2\n"
        expected_sha = sha256_bytes(content.encode("utf-8"))
        gate = self.p("gate")

        procs = []
        for index in range(2):
            body = textwrap.dedent(f"""
                import json, os, sys, time
                import contract_v2 as C
                import txn as T
                p = C.Project({self.tmp!r})
                deadline = time.time() + 60
                while not os.path.exists({gate!r}):
                    if time.time() > deadline:
                        print(json.dumps({{"ok": False, "error": "gate timeout"}}))
                        sys.exit(3)
                    time.sleep(0.002)
                t = T.Transaction(p, run_id="race-{index}", label="shared",
                                  parent="root")
                t.stage("results/shared.csv", {content!r})
                try:
                    manifest = t.commit(message="race")
                except Exception as exc:
                    print(json.dumps({{"ok": False,
                                       "error": type(exc).__name__ + ": "
                                                + str(exc)}}))
                else:
                    print(json.dumps({{"ok": True,
                                       "commit": manifest["commit"]}}))
            """)
            procs.append(self.start_child(body))

        time.sleep(0.5)                      # let both children reach the gate
        Path(gate).write_text("go", encoding="utf-8")
        results = []
        for proc in procs:
            out, err = proc.communicate(timeout=180)
            self.assertEqual(proc.returncode, 0, err)
            results.append(self.last_json(out))

        succeeded = [r for r in results if r["ok"]]
        failed = [r for r in results if not r["ok"]]
        self.assertGreaterEqual(len(succeeded), 1,
                                f"no writer completed: {results}")
        self.assertEqual(len(succeeded) + len(failed), 2)
        for failure in failed:
            self.assertTrue(failure["error"], failure)

        # either one writer wins, or both wrote the same idempotent commit
        commit_ids = {r["commit"] for r in succeeded}
        self.assertEqual(len(commit_ids), 1,
                         f"two different commits were accepted: {commit_ids}")
        commit_id = commit_ids.pop()

        pointer = T.read_pointer(proj)
        manifest = T.read_manifest(proj)
        self.assertEqual(pointer["commit"], commit_id)
        self.assertEqual(manifest["commit"], commit_id)

        # the pointer and the manifest describe exactly one current version
        targets = {e["target"]: e["sha256"] for e in manifest["entries"]}
        self.assertEqual(pointer["targets"], targets)
        self.assertEqual(list(targets), ["results/shared.csv"])
        self.assertEqual(targets["results/shared.csv"], expected_sha)
        self.assertEqual(sha256_path(proj.path("objects", expected_sha)),
                         expected_sha)
        self.assertTrue(T.verify_commit(proj))
        self.assertEqual(T.read_published(proj, "results/shared.csv"),
                         content.encode("utf-8"))
        self.assertEqual(len(list(proj.path("commits").glob("*.json"))), 1,
                         "idempotent writers must not create two manifests")

        # a writer that lost the race must not look published
        for index, result in enumerate(results):
            if result["ok"]:
                continue
            state = T.recover(proj, f"race-{index}")
            self.assertFalse(state.get("published", False), state)
        print(f"[race] writers={results} commit={commit_id}")
